/**
 * Bundle the vendored CSS (Google Fonts @font-face rules, Bootstrap, and
 * Font Awesome) into a single css/vendor.css file.
 *
 * Run with:  npm run bundle-vendor
 *
 * The font URLs inside each source file are relative to that file's location,
 * so they are rewritten to resolve correctly from css/vendor.css (one level
 * up, in the css/ directory).
 *
 * Run this after `npm run purge`, so the purged bootstrap.min.css and
 * fontawesome/*.css files are the inputs.
 */
const fs = require('fs');
const path = require('path');
const CleanCSS = require('clean-css');

const root = path.resolve(__dirname, '..');
const cssDir = path.join(root, 'css');

// [source path relative to cssDir, [search, replace] for font URLs, or null]
const SOURCES = [
  ['googlefonts/google-open-sans.css', ['../../fonts/', '../fonts/']],
  ['googlefonts/google-montserrat.css', ['../../fonts/', '../fonts/']],
  ['googlefonts/google-anonymous-pro.css', ['../../fonts/', '../fonts/']],
  ['bootstrap.min.css', null],
  ['fontawesome/v7/fontawesome.min.css', ['../../../fonts/', '../fonts/']],
  ['fontawesome/v7/brands.min.css', ['../../../fonts/', '../fonts/']],
  ['fontawesome/v7/solid.min.css', ['../../../fonts/', '../fonts/']],
];

const chunks = [];

for (const [rel, rewrite] of SOURCES) {
  let css = fs.readFileSync(path.join(cssDir, rel), 'utf8');
  css = css.replace(/^\uFEFF/, '').replace(/@charset[^;]*;?/i, '');
  if (rewrite) {
    css = css.split(rewrite[0]).join(rewrite[1]);
  }
  chunks.push(`/* ${rel} */\n${css.trim()}\n`);
}

const out = [
  '@charset "UTF-8";',
  '/*! Bundled vendor CSS — generated by scripts/bundle-vendor-css.js. */',
  chunks.join('\n'),
].join('\n');

const outFile = path.join(cssDir, 'vendor.css');

// Minify the bundle. The leading /*! banner and other /*! attribution
// comments are preserved (CleanCSS treats them as "special" comments).
const minified = new CleanCSS({ level: 2 }).minify(out);
if (minified.errors.length) {
  console.error(minified.errors);
  process.exit(1);
}
fs.writeFileSync(outFile, minified.styles);
console.log(`Wrote ${path.relative(root, outFile)} (${minified.styles.length} chars, minified from ${out.length})`);
